postorder(root):
    p=root; last=NULL; 建空栈 S
    while p 非空 or S 非空:
        if p 非空:
            push(S,p); p=p->left
        else:
            q=top(S)
            if q->right 非空 and last!=q->right:
                p=q->right
            else:
                visit(q); last=pop(S)
\end{codeblock}

