void siftDown(int A[], int root, int n) {
    int x=A[root];
    for (int c=2*root; c<=n; c=2*root) {
        if (c<n && A[c]<A[c+1]) ++c;
        if (x>=A[c]) break;
        A[root]=A[c];
        root=c;
    }
    A[root]=x;
}
\end{codeblock}

